1	/**
2	 * @module templates/aspire/generate-aspire-config
3	 *
4	 * Tier 1 generator for `aspire.config.json` (project root).
5	 *
6	 * Produces the minimal Aspire CLI configuration pointing to the AppHost
7	 * project directory.
8	 */
9	
10	import { SCAFFOLD_ASPIRE_INTEGRATIONS } from '../../constants/scaffold/scaffold-aspire.ts';
11	import { SCAFFOLD_DEFAULTS } from '../../constants/scaffold/scaffold-defaults.ts';
12	import { SCAFFOLD_VERSIONS } from '../../constants/scaffold/scaffold-versions.ts';
13	import type { CacheBackendChoice } from '../../domain/cache-backend.ts';
14	import type { DbEngineChoice } from '../../domain/db-engine.ts';
15	
16	const ASPIRE_EPHEMERAL_PORT = 0;
17	
18	/** Options for generating `aspire.config.json`. */
19	export interface AspireConfigOptions {
20	  /** Path to the AppHost project relative to the workspace root. */
21	  readonly appHostPath?: string;
22	}
23	
24	/**
25	 * Generate the contents of `aspire.config.json`.
26	 *
27	 * @param options - Optional overrides for AppHost path.
28	 * @returns Serialized JSON string with trailing newline.
29	 */
30	export function generateAspireConfig(options?: AspireConfigOptions): string {
31	  const config = {
32	    appHostPath: options?.appHostPath ?? SCAFFOLD_DEFAULTS.ASPIRE_TS_APPHOST_PATH,
33	  };
34	  return JSON.stringify(config, null, 2) + '\n';
35	}
36	
37	/**
38	 * Options controlling which NuGet integration packages are declared in the
39	 * TypeScript AppHost `aspire.config.json`. Each flag toggles an
40	 * `[AspireExport]`-annotated NuGet. Without the matching package,
41	 * `aspire restore` omits the capability from `.aspire/modules/aspire.mts`, and the
42	 * generated `.helpers/register-*.ts` call (e.g. `builder.addPostgres(...)`)
43	 * throws at runtime.
44	 *
45	 * ### Deno orchestration — intentionally no NuGet
46	 *
47	 * Aspire 13.5 can project the CommunityToolkit Deno integration's
48	 * `addDenoApp(...)` and `addDenoTask(...)` APIs after restore. NetScript 0.0.7
49	 * deliberately keeps the SDK primitive `builder.addExecutable('deno', ...)`
50	 * until the S12 adoption slice proves the projected integration through the
51	 * full scaffold runtime gate. First-party Deno hosting is scheduled upstream
52	 * for Aspire 13.6 (aspire#18627, aspire#18628, and aspire#16218).
53	 */
54	export interface TsAspireConfigOptions {
55	  /** Selected database engine (drives Postgres/MySql packages). */
56	  readonly dbEngine?: DbEngineChoice;
57	  /** All configured database engines when more than one is present. */
58	  readonly dbEngines?: readonly DbEngineChoice[];
59	  /** Selected cache backend. */
60	  readonly cacheBackend?: CacheBackendChoice;
61	  /** Whether a cache resource is configured. */
62	  readonly cache?: boolean;
63	}
64	
65	/**
66	 * Generate the contents of `aspire.config.json` for TypeScript AppHost mode.
67	 *
68	 * Produces the configuration for `aspire start` / `aspire restore` pointing
69	 * to `apphost.mts` as the TypeScript entry point. The `packages` section is
70	 * populated based on `options` so every `builder.addXxx(...)` capability
71	 * emitted by the helpers generator has a matching SDK export after
72	 * `aspire restore` rebuilds `.aspire/modules/aspire.mts`.
73	 *
74	 * @param options - Which integration packages the scaffold needs.
75	 * @returns Serialized JSON string with trailing newline.
76	 */
77	export function generateTsAspireConfig(options?: TsAspireConfigOptions): string {
78	  const packages: Record<string, string> = {};
79	  const dbEngines = options?.dbEngines ??
80	    (options?.dbEngine ? [options.dbEngine] : []);
81	
82	  // Database integrations — mirror the engine→method map in
83	  // generate-register-infrastructure.ts (Postgres/addPostgres,
84	  // Mysql/addMySql, Mssql/addSqlServer, Sqlite/addConnectionString
85	  // (no NuGet needed)).
86	  // These are official Microsoft NuGets whose `[AspireExport]` wrappers are
87	  // correctly re-emitted into `.aspire/modules/aspire.mts` by `aspire restore`,
88	  // unlike the community Deno one — see the comment
89	  // on `TsAspireConfigOptions` above.
90	  for (const engine of dbEngines) {
91	    switch (engine) {
92	      case 'postgres':
93	        packages[SCAFFOLD_ASPIRE_INTEGRATIONS.POSTGRES.PACKAGE_ID] =
94	          SCAFFOLD_ASPIRE_INTEGRATIONS.POSTGRES.VERSION;
95	        break;
96	      case 'mysql':
97	        packages[SCAFFOLD_ASPIRE_INTEGRATIONS.MYSQL.PACKAGE_ID] =
98	          SCAFFOLD_ASPIRE_INTEGRATIONS.MYSQL.VERSION;
99	        break;
100	      case 'mssql':
101	        packages[SCAFFOLD_ASPIRE_INTEGRATIONS.MSSQL.PACKAGE_ID] =
102	          SCAFFOLD_ASPIRE_INTEGRATIONS.MSSQL.VERSION;
103	        break;
104	      case 'sqlite':
105	      case 'none':
106	        // No integration NuGet needed.
107	        break;
108	    }
109	  }
110	
111	  if (options?.cache !== false && options?.cacheBackend !== 'deno-kv') {
112	    const integration = options?.cacheBackend === 'garnet'
113	      ? SCAFFOLD_ASPIRE_INTEGRATIONS.GARNET
114	      : SCAFFOLD_ASPIRE_INTEGRATIONS.REDIS;
115	    packages[integration.PACKAGE_ID] = integration.VERSION;
116	  }
117	
118	  packages[SCAFFOLD_ASPIRE_INTEGRATIONS.BROWSERS.PACKAGE_ID] =
119	    SCAFFOLD_ASPIRE_INTEGRATIONS.BROWSERS.VERSION;
120	
121	  const config: Record<string, unknown> = {
122	    appHost: {
123	      path: 'apphost.mts',
124	      language: 'typescript/nodejs',
125	    },
126	    sdk: {
127	      version: SCAFFOLD_VERSIONS.ASPIRE_SDK,
128	    },
129	    profiles: {
130	      https: {
131	        applicationUrl:
